from bisect import bisect_right

def longest_nest(crates):
    groups = {}
    for w, h in crates:
        groups.setdefault(w, []).append(h)
    tails = []
    for w in sorted(groups):
        moves = {}
        for h in groups[w]:
            k = bisect_right(tails, h)
            if k not in moves or h < moves[k]:
                moves[k] = h
        for k in sorted(moves):
            if k == len(tails):
                tails.append(moves[k])
            elif moves[k] < tails[k]:
                tails[k] = moves[k]
    return len(tails)

