def longest_nest(crates):
    order = sorted(crates)
    n = len(order)
    best = [1] * n
    for i in range(n):
        for j in range(i):
            if order[j][0] < order[i][0] and order[j][1] <= order[i][1] and best[j] + 1 > best[i]:
